import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_transposed_conv3d_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Naive GPU kernel for transposed convolution 3D (stride, padding, output_padding supported, groups=1, dilation=1)
__global__ void transposed_conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int B,          // batch size
    const int Cin,        // input channels
    const int Din,        // input depth
    const int Hin,        // input height
    const int Win,        // input width
    const int Cout,       // output channels
    const int Kd,         // kernel depth
    const int Kh,         // kernel height
    const int Kw,         // kernel width
    const int outD,       // output depth
    const int outH,       // output height
    const int outW,       // output width
    const int strideD,
    const int strideH,
    const int strideW,
    const int padD,
    const int padH,
    const int padW,
    const int outPadD,
    const int outPadH,
    const int outPadW,
    const bool hasBias
) {
    // Each thread will compute a single output element: (b, c_out, od, oh, ow)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * Cout * outD * outH * outW;
    if (idx >= total) return;

    // Decompose idx into b, c_out, od, oh, ow
    int ow = idx % outW; 
    int tmp = idx / outW;
    int oh = tmp % outH;
    tmp = tmp / outH;
    int od = tmp % outD;
    tmp = tmp / outD;
    int c_out = tmp % Cout;
    int b = tmp / Cout;

    float sumVal = 0.0f;

    // Loop over input channels, kernel dims
    for(int c_in = 0; c_in < Cin; c_in++) {
        for(int kd = 0; kd < Kd; kd++) {
            int pd = od + padD - kd;
            // Check stride/dilation (dilation=1)
            if (pd < 0 || (pd % strideD) != 0) continue;
            int id = pd / strideD;
            if (id < 0 || id >= Din) continue;

            for(int kh = 0; kh < Kh; kh++) {
                int ph = oh + padH - kh;
                if (ph < 0 || (ph % strideH) != 0) continue;
                int ih = ph / strideH;
                if (ih < 0 || ih >= Hin) continue;

                for(int kw = 0; kw < Kw; kw++) {
                    int pw = ow + padW - kw;
                    if (pw < 0 || (pw % strideW) != 0) continue;
                    int iw = pw / strideW;
                    if (iw < 0 || iw >= Win) continue;

                    // weight layout = [Cin, Cout, kd, kh, kw]
                    int wIndex = c_in * (Cout * Kd * Kh * Kw)
                                 + c_out * (Kd * Kh * Kw)
                                 + kd * (Kh * Kw)
                                 + kh * Kw
                                 + kw;
                    // input layout = [B, Cin, Din, Hin, Win]
                    int iIndex = b * (Cin * Din * Hin * Win)
                                 + c_in * (Din * Hin * Win)
                                 + id * (Hin * Win)
                                 + ih * Win
                                 + iw;
                    sumVal += input[iIndex] * weight[wIndex];
                }
            }
        }
    }
    if (hasBias) {
        sumVal += bias[c_out];
    }

    // output layout = [B, Cout, outD, outH, outW]
    int outIndex = b * (Cout * outD * outH * outW)
                   + c_out * (outD * outH * outW)
                   + od * (outH * outW)
                   + oh * outW
                   + ow;
    output[outIndex] = sumVal;
}

// Forward pass for transposed_conv3d
torch::Tensor transposed_conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias_opt,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outPadD, int outPadH, int outPadW
) {
    // input shape: [B, Cin, Din, Hin, Win]
    // weight shape: [Cin, Cout, Kd, Kh, Kw] (nn.ConvTranspose3d style)
    // bias shape: [Cout] (optional)
    auto input_sizes = input.sizes();
    auto weight_sizes = weight.sizes();

    const int B = input_sizes[0];
    const int Cin = input_sizes[1];
    const int Din = input_sizes[2];
    const int Hin = input_sizes[3];
    const int Win = input_sizes[4];

    const int Kd = weight_sizes[2];
    const int Kh = weight_sizes[3];
    const int Kw = weight_sizes[4];
    const int Cout = weight_sizes[1];

    // Dilation = 1
    // output size formula for transposed conv: (in_dim - 1)*stride - 2*pad + (kernel_size) + outPad
    const int outD = (Din - 1) * strideD - 2*padD + Kd + outPadD;
    const int outH = (Hin - 1) * strideH - 2*padH + Kh + outPadH;
    const int outW = (Win - 1) * strideW - 2*padW + Kw + outPadW;

    // Create output tensor
    auto out_options = input.options().dtype(input.dtype());
    auto output = torch::zeros({B, Cout, outD, outH, outW}, out_options);

    bool hasBias = bias_opt.has_value();
    const float* bias_ptr = nullptr;
    if(hasBias) {
        bias_ptr = bias_opt.value().data_ptr<float>();
    }

    // Launch kernel
    int total = B * Cout * outD * outH * outW;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    transposed_conv3d_forward_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr == nullptr ? nullptr : bias_ptr,
        output.data_ptr<float>(),
        B, Cin, Din, Hin, Win,
        Cout, Kd, Kh, Kw,
        outD, outH, outW,
        strideD, strideH, strideW,
        padD, padH, padW,
        outPadD, outPadH, outPadW,
        hasBias
    );
    return output;
}
"""

_transposed_conv3d_cpp_src = r"""
torch::Tensor transposed_conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outPadD, int outPadH, int outPadW
);
"""

# Compile the extension
_transposed_conv3d = load_inline(
    name="transposed_conv3d",
    cpp_sources=_transposed_conv3d_cpp_src,
    cuda_sources=_transposed_conv3d_src,
    functions=["transposed_conv3d_forward_cuda"],
    verbose=False
)


class ModelNew(nn.Module):
    """
    Custom 3D transposed convolution using a naive CUDA kernel.
    Same args as the original Model, ignoring groups>1 and dilation>1.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1, 1),
        padding: tuple = (0, 0, 0),
        output_padding: tuple = (0, 0, 0),
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        # Store parameters
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.use_bias = bias

        # Weight shape for ConvTranspose3d: [in_channels, out_channels, kd, kh, kw]
        kd, kh, kw = kernel_size
        w = torch.randn(in_channels, out_channels, kd, kh, kw) * 0.01
        self.weight = nn.Parameter(w)
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _transposed_conv3d.transposed_conv3d_forward_cuda(
            x,
            self.weight,
            self.bias if self.use_bias else None,
            self.stride[0],
            self.stride[1],
            self.stride[2],
            self.padding[0],
            self.padding[1],
            self.padding[2],
            self.output_padding[0],
            self.output_padding[1],
            self.output_padding[2]
        )
